import React, { useState } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [showQR, setShowQR] = useState(false);
  const [screenshot, setScreenshot] = useState(null);
  const [statusMsg, setStatusMsg] = useState("");
  const [approved, setApproved] = useState(false);

  /* INPUT HANDLE */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* SHOW PAYMENT */
  const handlePayment = (e) => {
    e.preventDefault();
    setShowQR(true);
  };

  /* SUBMIT WITH SCREENSHOT */
  const confirmPayment = async () => {
    if (!screenshot) {
      return alert("⚠️ Screenshot upload pannunga!");
    }

    // File size check (max 2MB)
    if (screenshot.size > 2 * 1024 * 1024) {
      return alert("❌ File too large (max 2MB)");
    }

    const form = new FormData();

    Object.keys(formData).forEach((key) => {
      form.append(key, formData[key]);
    });

    form.append("screenshot", screenshot);

    try {
      const res = await axios.post(
        "http://localhost:5000/register",
        form,
        {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        }
      );

      if (res.data.success) {
        setStatusMsg("⏳ Waiting for admin approval");
        alert("✅ Payment submitted successfully");
      } else {
        alert(res.data.message);
      }
    } catch (err) {
      console.error("UPLOAD ERROR:", err);
      alert("❌ Upload failed");
    }
  };

  /* UPI STRING (FIXED) */
  const upiString = `upi://pay?pa=arunsekar664@okaxis&pn=Event&am=100&cu=INR`;

  /* STYLES */
  const box = {
    padding: "20px",
    borderRadius: "10px",
    background: "#222",
    width: "300px",
    margin: "auto",
  };

  const input = {
    padding: "10px",
    margin: "5px",
    width: "100%",
  };

  const btn = {
    padding: "10px",
    background: "orange",
    border: "none",
    cursor: "pointer",
  };

  return (
    <div style={{ textAlign: "center", color: "white" }}>
      <Navbar />
      <h2>🚀 Event Registration</h2>

      {/* FORM */}
      {!showQR && (
        <form onSubmit={handlePayment} style={box}>
          <input
            name="name"
            placeholder="Name"
            style={input}
            onChange={handleChange}
            required
          />
          <input
            name="college_name"
            placeholder="College"
            style={input}
            onChange={handleChange}
            required
          />
          <input
            name="phone"
            placeholder="Phone"
            style={input}
            onChange={handleChange}
            required
          />
          <input
            name="email"
            placeholder="Email"
            style={input}
            onChange={handleChange}
            required
          />

          <h3>{eventName}</h3>

          <button style={btn}>Proceed to Pay</button>
        </form>
      )}

      {/* PAYMENT */}
      {showQR && (
        <div style={box}>
          <h3>📲 Scan & Pay</h3>
          <QRCode value={upiString} size={200} />

          <p>Pay ₹100 and upload screenshot</p>

          <input
            type="file"
            accept="image/*"
            onChange={(e) => setScreenshot(e.target.files[0])}
          />

          {/* Preview */}
          {screenshot && (
            <img
              src={URL.createObjectURL(screenshot)}
              alt="preview"
              style={{ width: "100px", marginTop: "10px" }}
            />
          )}

          <button style={btn} onClick={confirmPayment}>
            Submit Payment
          </button>

          {statusMsg && <p>{statusMsg}</p>}
        </div>
      )}
    </div>
  );
}

export default Register;
